// Generated by horizon-port from Classic Farlands 1.3.3+mc26.3, then finished by hand: the mod's Java
// that calls the game, translated to Horizon's native helpers. Methods it couldn't translate are listed
// in report/translation.md.
#[allow(unused_imports)]
use crate::game::port_classicfarlands::java::*;
#[allow(unused_imports)]
use std::sync::LazyLock;

/// ClassicFarlands.onInitialize (archives/tater/classicfarlands/ClassicFarlands.java:38), without its
/// Fabric registrations: the SERVER_STARTING listener is `on_server_starting` (the `server-starting`
/// hook) and the Mixson event is the `final-density` injection. Nothing else runs at initialisation.
pub fn on_init(_game: &mut crate::game::Game<'_>) {}

static INIT: std::sync::Once = std::sync::Once::new();

/// Called first by every hook: points FabricLoader's config folder at the mod's data folder, then runs
/// the mod's initializer, once.
pub fn ensure_init(game: &mut crate::game::Game<'_>) {
    if INIT.is_completed() {
        return;
    }
    INIT.call_once(|| {
        J_DATA_DIR.set(Some(game.native_data_dir(crate::game::port_classicfarlands::ID)));
        on_init(game);
    });
}

/// The `distance` of config/classicfarlands.toml, which is written with its default when missing (as
/// the Fabric mod's config library does). An unreadable folder or an unusable value keeps the default.
fn configured_distance() -> i32 {
    use crate::game::port_classicfarlands_config as config;
    let Ok(dir) = crate::game::Game::native_config_dir() else {
        return config::DEFAULT_DISTANCE;
    };
    let path = dir.join(config::FILE_NAME);
    match std::fs::read_to_string(&path) {
        Ok(text) => config::parse_distance(&text).unwrap_or(config::DEFAULT_DISTANCE),
        Err(_) => {
            let _ = std::fs::write(&path, config::DEFAULT_FILE);
            config::DEFAULT_DISTANCE
        }
    }
}

/// ServerLifecycleEvents.SERVER_STARTING: `COORDINATE_DISTANCE = 4 * (CONFIG.distance / 4) - 2`, set
/// before any world loads. The density switch distance (`4 * (distance / 4) - 3`) is read from the
/// same state when the worldgen data is loaded, which happens after this.
pub fn on_server_starting(game: &mut crate::game::Game<'_>) {
    ensure_init(game);
    use horizon_core::noise::port_classicfarlands_state as state;
    state::set_distance(configured_distance());
    classic_farlands::COORDINATE_DISTANCE.set(state::coordinate_distance());
}

// The mod's row in Options > Mods, and its keys (name, label, default key).
fn classicfarlands_listed(mods: &mut Vec<crate::game::native_hooks::NativeMod>) {
    use crate::game::port_classicfarlands as m;
    mods.push(crate::game::native_hooks::NativeMod {
        id: m::ID.into(),
        title: format!("{} {}", m::NAME, m::VERSION),
        description: m::DESCRIPTION.into(),
        keys: m::KEYS.iter().map(|[n, l, d]| [n.to_string(), l.to_string(), d.to_string()]).collect(),
    });
}
